<?php
namespace App\Domain\Testimonials; use App\Domain\PublicChrome\PublicAssetPath; use App\Models\Testimonial; use Illuminate\Support\Facades\Cache; use Throwable; final class TestimonialViewData { public function published():array{try{return Cache::remember('public.testimonials.v1.'.TestimonialCache::version().'.'.now()->format('YmdHi'),now()->addMinutes(10),fn()=>$this->load());}catch(Throwable){return $this->load();}} public function preview(Testimonial $item):array{return $this->transform($item->load('client'));} private function load():array{return Testimonial::publiclyVisible()->with(['client'=>fn($q)=>$q->publiclyVisible()])->orderByDesc('is_featured')->orderBy('display_order')->limit(100)->get()->map(fn($x)=>$this->transform($x))->all();} private function transform(Testimonial $x):array{return ['person_name'=>$x->person_name,'designation'=>$x->designation,'organization'=>$x->client?->isPubliclyVisible()?$x->client->name:$x->organization_name,'quote'=>$x->quote,'image'=>PublicAssetPath::isSafe($x->image_path)?$x->image_path:null,'image_alt'=>$x->image_alt,'rating'=>$x->rating];} }
